<?php
require_once dirname(__DIR__).'/config/database.php';require_once dirname(__DIR__).'/includes/layout.php';require_login('admin');$edit=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='save'){$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);$code=strtoupper(trim($_POST['code']??''));$title=trim($_POST['title']??'');$description=trim($_POST['description']??'');$duration=trim($_POST['duration']??'');if(!preg_match('/^[A-Z0-9-]{2,30}$/',$code)||$title===''||$description===''||$duration===''){flash('Complete all course fields and use a short course code.','error');redirect('admin/courses.php'.($id?'?edit='.$id:''));}try{if($id)$pdo->prepare('UPDATE courses SET code=?,title=?,description=?,duration=? WHERE id=?')->execute([$code,$title,$description,$duration,$id]);else $pdo->prepare("INSERT INTO courses(code,title,description,duration,status) VALUES(?,?,?,?,'active')")->execute([$code,$title,$description,$duration]);flash($id?'Course details updated.':'Course created.');}catch(PDOException $e){if($e->getCode()==='23000')flash('That course code is already in use.','error');else throw $e;}redirect('admin/courses.php');}if($action==='archive'){$id=(int)($_POST['id']??0);$pdo->prepare("UPDATE courses SET status=IF(status='active','archived','active') WHERE id=?")->execute([$id]);flash('Course availability updated.');redirect('admin/courses.php');}}
if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM courses WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$courses=$pdo->query('SELECT c.*,(SELECT COUNT(*) FROM enrollments e WHERE e.course_id=c.id) AS learners FROM courses c ORDER BY c.created_at DESC')->fetchAll();start_page('Manage courses','courses'); ?>
<div class="grid gap-5 xl:grid-cols-[360px_1fr]"><section class="card h-max"><p class="eyebrow"><?= $edit?'UPDATE LISTING':'NEW LISTING' ?></p><h2 class="card-title mt-2"><?= $edit?'Edit course':'Create a course' ?></h2><form method="post" class="mt-5 space-y-4"><?= csrf_field() ?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><div><label class="field-label">Course code</label><input class="field" name="code" required maxlength="30" placeholder="WIS-101" value="<?= e($edit['code']??'') ?>"></div><div><label class="field-label">Course title</label><input class="field" name="title" required maxlength="160" value="<?= e($edit['title']??'') ?>"></div><div><label class="field-label">Duration</label><input class="field" name="duration" required maxlength="80" placeholder="6 weeks" value="<?= e($edit['duration']??'') ?>"></div><div><label class="field-label">Description</label><textarea class="field min-h-28" name="description" required><?= e($edit['description']??'') ?></textarea></div><button class="btn-primary w-full"><?= $edit?'Save changes':'Add course' ?></button><?php if($edit): ?><a class="btn-secondary w-full" href="<?= e(app_url('admin/courses.php')) ?>">Cancel editing</a><?php endif ?></form></section><section><p class="muted mb-3">Archived courses are hidden from students while past enrollment records remain available.</p><div class="table-wrap"><table><thead><tr><th>Course</th><th>Duration</th><th>Students</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($courses as $c): ?><tr><td><span class="font-semibold"><?= e($c['title']) ?></span><div class="course-code mt-1"><?= e($c['code']) ?></div></td><td><?= e($c['duration']) ?></td><td><?= (int)$c['learners'] ?></td><td><span class="badge badge-<?= $c['status']==='active'?'success':'pending' ?>"><?= e($c['status']) ?></span></td><td><div class="flex gap-2"><a class="btn-secondary" href="<?= e(app_url('admin/courses.php?edit='.(int)$c['id'])) ?>">Edit</a><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="archive"><input type="hidden" name="id" value="<?= (int)$c['id'] ?>"><button class="<?= $c['status']==='active'?'btn-danger':'btn-secondary' ?>"><?= $c['status']==='active'?'Archive':'Restore' ?></button></form></div></td></tr><?php endforeach ?></tbody></table></div></section></div><?php end_page(); ?>
